export default function PengurusLoading() {
  return (
    <div className="h-[calc(100vh-140px)] flex flex-col font-sans">
      {/* HEADER SKELETON */}
      <div className="flex-shrink-0">
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-8 animate-pulse">
          <div className="space-y-3">
            <div className="h-10 w-64 bg-slate-200 dark:bg-slate-800 rounded-xl" />
            <div className="h-4 w-48 bg-slate-100 dark:bg-slate-800/50 rounded-lg" />
          </div>
          <div className="flex gap-3">
            <div className="h-12 w-32 bg-slate-100 dark:bg-slate-800 rounded-xl" />
            <div className="h-12 w-32 bg-blue-100 dark:bg-blue-900/30 rounded-xl" />
          </div>
        </div>

        {/* TOOLBAR SKELETON */}
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8 animate-pulse">
          <div className="flex gap-2 w-full md:w-auto">
            {[1, 2, 3, 4].map(i => <div key={i} className="h-10 w-20 bg-slate-50 dark:bg-slate-800 rounded-xl" />)}
          </div>
          <div className="h-10 w-full md:w-64 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl" />
        </div>
      </div>

      {/* GRID SKELETON */}
      <div className="flex-1 overflow-hidden">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <div key={i} className="bg-white dark:bg-[#0f172a]/40 border border-slate-200 dark:border-white/5 rounded-3xl p-6 h-[280px] flex flex-col items-center relative overflow-hidden">
              {/* Shimmer Effect */}
              <div className="absolute inset-0 -translate-x-full animate-[shimmer_2s_infinite] bg-gradient-to-r from-transparent via-white/10 to-transparent" />
              <div className="w-20 h-20 rounded-full bg-slate-200 dark:bg-slate-800 mb-4" />
              <div className="h-5 w-32 bg-slate-200 dark:bg-slate-800 rounded mb-2" />
              <div className="h-3 w-20 bg-slate-100 dark:bg-slate-800/50 rounded mb-6" />
              <div className="w-full pt-4 border-t border-slate-50 dark:border-white/5 flex justify-between">
                <div className="flex gap-2"><div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800" /><div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800" /></div>
                <div className="flex gap-2"><div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800" /><div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800" /></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
